-- Permission vocabulary and system roles of the edi module
-- Generated by metaphor-schema
--
-- Writes into the identity module's tables (public.permissions, public.roles,
-- public.role_permissions), so those migrations must have run first. Inserts what is
-- missing and never deletes or revokes: what a tenant changed survives a re-run.

DO $$
BEGIN
    IF to_regclass('public.permissions') IS NULL
       OR to_regclass('public.roles') IS NULL
       OR to_regclass('public.role_permissions') IS NULL THEN
        RAISE NOTICE 'seed of the edi permissions skipped: the identity module has not created public.permissions, public.roles and public.role_permissions';
        RETURN;
    END IF;

    UPDATE public.permissions p SET description = v.description
      FROM (VALUES
            ('edi_document:create'::text, 'edi_document'::text, 'create'::text, 'Create edi document'::text),
            ('edi_document:delete'::text, 'edi_document'::text, 'delete'::text, 'Delete edi document'::text),
            ('edi_document:purge'::text, 'edi_document'::text, 'purge'::text, 'Purge edi document'::text),
            ('edi_document:read'::text, 'edi_document'::text, 'read'::text, 'Read edi document'::text),
            ('edi_document:restore'::text, 'edi_document'::text, 'restore'::text, 'Restore edi document'::text),
            ('edi_document:update'::text, 'edi_document'::text, 'update'::text, 'Update edi document'::text),
            ('trading_partner:create'::text, 'trading_partner'::text, 'create'::text, 'Create trading partner'::text),
            ('trading_partner:delete'::text, 'trading_partner'::text, 'delete'::text, 'Delete trading partner'::text),
            ('trading_partner:purge'::text, 'trading_partner'::text, 'purge'::text, 'Purge trading partner'::text),
            ('trading_partner:read'::text, 'trading_partner'::text, 'read'::text, 'Read trading partner'::text),
            ('trading_partner:restore'::text, 'trading_partner'::text, 'restore'::text, 'Restore trading partner'::text),
            ('trading_partner:update'::text, 'trading_partner'::text, 'update'::text, 'Update trading partner'::text)
      ) AS v(name, resource, action, description)
     WHERE p.name = v.name AND (p.metadata->>'deleted_at') IS NULL
       AND p.description IS DISTINCT FROM v.description;

    INSERT INTO public.permissions (name, resource, action, description)
    SELECT v.name, v.resource, v.action, v.description
      FROM (VALUES
            ('edi_document:create'::text, 'edi_document'::text, 'create'::text, 'Create edi document'::text),
            ('edi_document:delete'::text, 'edi_document'::text, 'delete'::text, 'Delete edi document'::text),
            ('edi_document:purge'::text, 'edi_document'::text, 'purge'::text, 'Purge edi document'::text),
            ('edi_document:read'::text, 'edi_document'::text, 'read'::text, 'Read edi document'::text),
            ('edi_document:restore'::text, 'edi_document'::text, 'restore'::text, 'Restore edi document'::text),
            ('edi_document:update'::text, 'edi_document'::text, 'update'::text, 'Update edi document'::text),
            ('trading_partner:create'::text, 'trading_partner'::text, 'create'::text, 'Create trading partner'::text),
            ('trading_partner:delete'::text, 'trading_partner'::text, 'delete'::text, 'Delete trading partner'::text),
            ('trading_partner:purge'::text, 'trading_partner'::text, 'purge'::text, 'Purge trading partner'::text),
            ('trading_partner:read'::text, 'trading_partner'::text, 'read'::text, 'Read trading partner'::text),
            ('trading_partner:restore'::text, 'trading_partner'::text, 'restore'::text, 'Restore trading partner'::text),
            ('trading_partner:update'::text, 'trading_partner'::text, 'update'::text, 'Update trading partner'::text)
      ) AS v(name, resource, action, description)
     WHERE NOT EXISTS (SELECT 1 FROM public.permissions p WHERE p.name = v.name AND (p.metadata->>'deleted_at') IS NULL)
    ON CONFLICT DO NOTHING;

END $$;
